insert into kafaa_organisations (id, name_en, name_ar, short, kind, category, categories, rel_types, relationship_en, relationship_ar, status, dates, country, binding, public_listed, synthetic, nexus_org_id, icv_score, sources, contact_route) values
('org-dhafra-tech', 'Al Dhafra Technical Institute (synthetic)', 'معهد الظفرة التقني (افتراضي)', 'ADTI', 'university', 'synthetic', array['synthetic']::text[], array['provider']::text[], 'Synthetic local training provider in the FS64 regional skills plan demo.', 'جهة تدريب محلية افتراضية في عرض خطة المهارات الإقليمية.', 'active', '', 'AE', false, false, true, null, null, '[]'::jsonb, null),
('org-ruwais-vti', 'Ruwais Vocational Training Institute (synthetic)', 'معهد الرويس للتدريب المهني (افتراضي)', 'RVTI', 'university', 'synthetic', array['synthetic']::text[], array['provider']::text[], 'Synthetic vocational training provider in the FS64 regional skills plan demo.', 'جهة تدريب مهني افتراضية في عرض خطة المهارات الإقليمية.', 'active', '', 'AE', false, false, true, null, null, '[]'::jsonb, null)
insert into kafaa_hc_metrics (id, key, iso_area, name_en, name_ar, definition_en, definition_ar, formula_en, formula_ar, source_en, source_ar, source_tables, owner_function, owner_person_id, owner_en, owner_ar, unit, basis, better, benchmark_ids, status, sort, version, simulated) values
('hcm-trained', 'trained_pct', 'skills_capabilities_development', 'Workforce trained this year', 'نسبة القوى العاملة المدرَّبة هذا العام', 'Share of active staff with at least one completed learning record between 1 January and the last day of the quarter. The headline coverage KPI.', 'نسبة الموظفين النشطين الذين لديهم سجل تعلّم مكتمل واحد على الأقل بين 1 يناير وآخر يوم في الربع. وهو مؤشر التغطية الرئيسي.', 'People with a training record (passed, completed or attended) or a completed or passed learning-record-store statement, 1 January to quarter end, divided by active staff, times 100. Under 10 people: suppressed.', 'عدد الأشخاص الذين لديهم سجل تدريب (ناجح أو مكتمل أو حضور) أو بيان مكتمل أو ناجح في مخزن سجلات التعلّم، من 1 يناير حتى نهاية الربع، مقسوماً على الموظفين النشطين، مضروباً في 100. أقل من 10 أشخاص: محجوب.', 'Training records (M04) and the learning record store (M27, xAPI)', 'سجلات التدريب (M04) ومخزن سجلات التعلّم (M27، xAPI)', array['training_records','xapi_statements','people']::text[], 'nuclear_training', 'p-training-mgr', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', 'pct', 'ytd', 'up', array['EU-PACT','ISO30414']::text[], 'active', 1, 1, true),
('hcm-active-learners', 'active_learners_pct', 'skills_capabilities_development', 'Quarterly active learners', 'المتعلّمون النشطون في الربع', 'Share of active staff with any recorded learning activity in the quarter: a course, refresher, simulator session, mentoring session, OJT task or knowledge asset.', 'نسبة الموظفين النشطين الذين لديهم أي نشاط تعلّم مسجّل خلال الربع: دورة أو تنشيط أو جلسة محاكي أو جلسة إرشاد أو مهمة تدريب أثناء العمل أو أصل معرفي.', 'People with at least one learning-record-store statement or training record dated in the quarter, divided by active staff, times 100. Under 10 people: suppressed.', 'عدد الأشخاص الذين لديهم بيان واحد على الأقل في مخزن سجلات التعلّم أو سجل تدريب مؤرخ في الربع، مقسوماً على الموظفين النشطين، مضروباً في 100. أقل من 10 أشخاص: محجوب.', 'Learning record store (M27, xAPI) and training records (M04)', 'مخزن سجلات التعلّم (M27، xAPI) وسجلات التدريب (M04)', array['training_records','xapi_statements','people']::text[], 'nuclear_training', 'p-training-mgr', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', 'pct', 'quarter', 'up', array['ISO30414']::text[], 'active', 2, 1, true),
('hcm-hours', 'hours_per_employee', 'skills_capabilities_development', 'Learning hours per employee', 'ساعات التعلّم لكل موظف', 'Recorded learning hours of active staff from 1 January to the end of the quarter, per active employee. Training-record hours count once, even though the same records also reach the learning record store.', 'ساعات التعلّم المسجّلة للموظفين النشطين من 1 يناير حتى نهاية الربع، لكل موظف نشط. تُحتسب ساعات سجلات التدريب مرة واحدة، رغم أن السجلات نفسها تصل أيضاً إلى مخزن سجلات التعلّم.', '(Training-record hours + durations on learning-record-store statements from every other source, a working day = 8 hours), 1 January to quarter end, divided by active staff; one decimal.', '(ساعات سجلات التدريب + المدد المسجّلة على بيانات مخزن سجلات التعلّم من كل المصادر الأخرى، واليوم الوظيفي = 8 ساعات)، من 1 يناير حتى نهاية الربع، مقسومة على الموظفين النشطين؛ برقم عشري واحد.', 'Training records (M04) and the learning record store (M27, xAPI)', 'سجلات التدريب (M04) ومخزن سجلات التعلّم (M27، xAPI)', array['training_records','xapi_statements','people']::text[], 'nuclear_training', 'p-training-mgr', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', 'hours', 'ytd', 'up', array['UAE-PEERS','ISO30414']::text[], 'active', 3, 1, true),
('hcm-ai-fundamentals', 'ai_fundamentals_pct', 'skills_capabilities_development', 'AI-fundamentals coverage', 'تغطية أساسيات الذكاء الاصطناعي', 'Share of active staff at rung 1 (Aware) or higher on the FS09 AI fluency ladder, from counted skill states; self-ratings never count. Measured on the day the values are computed.', 'نسبة الموظفين النشطين في الدرجة 1 (مُدرِك) أو أعلى على سلّم الطلاقة في الذكاء الاصطناعي، استناداً إلى حالات المهارات المحتسبة؛ ولا يُحتسب التقييم الذاتي أبداً. يُقاس في يوم حساب القيم.', 'People whose FS09 rung is 1 or more, divided by active staff, times 100. Under 10 people: suppressed.', 'عدد الأشخاص الذين تبلغ درجتهم 1 أو أكثر، مقسوماً على الموظفين النشطين، مضروباً في 100. أقل من 10 أشخاص: محجوب.', 'Skill states (F01) read through the FS09 AI fluency ladder (M29)', 'حالات المهارات (F01) مقروءة عبر سلّم الطلاقة في الذكاء الاصطناعي (M29)', array['person_skills','ai_rungs','ai_skill_tracks','people']::text[], 'digital_ai_governance', 'p-ai-governance', 'AI Governance Lead (role card)', 'قائد حوكمة الذكاء الاصطناعي (بطاقة دور)', 'pct', 'point', 'up', array['UAE-PEERS','ISO30414']::text[], 'active', 4, 1, true),
('hcm-critical', 'critical_on_track_pct', 'skills_capabilities_development', 'Critical future skills on track', 'مهارات المستقبل الحرجة على المسار', 'Share of adopted FS50 critical future skills whose computed progress is met or on track for the year, on the last day of the quarter. Rows whose progress is suppressed (under 10 people) or that have no target this year are left out and counted separately.', 'نسبة مهارات المستقبل الحرجة المعتمدة في السجل التي يكون تقدّمها المحسوب محققاً أو على المسار لهذا العام، في آخر يوم من الربع. تُستبعد الصفوف المحجوب تقدّمها (أقل من 10 أشخاص) أو التي لا هدف لها هذا العام وتُعدّ على حدة.', 'Adopted register rows with progress met or on track, divided by adopted rows with a measured progress, times 100 (register rows, not people).', 'صفوف السجل المعتمدة التي تقدّمها محقق أو على المسار، مقسومة على الصفوف المعتمدة ذات التقدّم المقاس، مضروبة في 100 (صفوف السجل، لا الأشخاص).', 'Critical Future-Skills Register (FS50, M35) and skill states (F01)', 'سجل مهارات المستقبل الحرجة (FS50، M35) وحالات المهارات (F01)', array['critical_skills','person_skills','workforce_snapshots']::text[], 'leadership_development', 'p-chco', 'Chief Human Capital Officer (role card)', 'الرئيس التنفيذي لرأس المال البشري (بطاقة دور)', 'pct', 'point', 'up', array['ISO30414']::text[], 'active', 5, 1, true),
('hcm-credits', 'credits_per_employee', 'skills_capabilities_development', 'Learning credits per employee', 'الأرصدة التعليمية لكل موظف', 'FS30 learning credits counted for active staff from 1 January to the end of the quarter, per active employee (10 notional hours = 1 credit; reversed credits never count).', 'الأرصدة التعليمية المحتسبة للموظفين النشطين من 1 يناير حتى نهاية الربع، لكل موظف نشط (10 ساعات تعلّم افتراضية = رصيد واحد؛ ولا تُحتسب الأرصدة الملغاة).', 'Notional hours of counted credit-ledger rows, 1 January to quarter end, divided by 10 and by active staff; two decimals.', 'الساعات الافتراضية لصفوف سجل الأرصدة المحتسبة، من 1 يناير حتى نهاية الربع، مقسومة على 10 وعلى الموظفين النشطين؛ برقمين عشريين.', 'Personal credit ledger (FS30, M34)', 'سجل الأرصدة الشخصي (FS30، M34)', array['credit_ledger','people']::text[], 'nuclear_training', 'p-training-mgr', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', 'credits', 'ytd', 'up', array['ISO30414']::text[], 'active', 6, 1, true),
('hcm-participation', 'participation_gap_pp', 'skills_capabilities_development', 'Participation gap by site, shift and grade', 'فجوة المشاركة حسب الموقع والوردية والدرجة الوظيفية', 'Who is not yet learning: the share trained this year for each site, shift crew and grade, and the largest gap between groups of one dimension. Groups under 10 people are suppressed; nationality and gender are never used.', 'من لم يبدأ التعلّم بعد: نسبة المدرَّبين هذا العام لكل موقع وطاقم وردية ودرجة وظيفية، وأكبر فجوة بين مجموعات البُعد الواحد. تُحجب المجموعات التي تقل عن 10 أشخاص؛ ولا تُستخدم الجنسية أو الجنس أبداً.', 'For each dimension, the highest minus the lowest share trained this year among groups with at least 10 people, in percentage points; the largest of the three. Lower is better.', 'لكل بُعد، أعلى نسبة مدرَّبين هذا العام ناقص أدناها بين المجموعات التي تضم 10 أشخاص على الأقل، بالنقاط المئوية؛ ويؤخذ الأكبر من الأبعاد الثلاثة. الأقل أفضل.', 'Training records (M04), the learning record store (M27) and the people directory (site, shift crew, grade)', 'سجلات التدريب (M04) ومخزن سجلات التعلّم (M27) ودليل الأشخاص (الموقع وطاقم الوردية والدرجة)', array['training_records','xapi_statements','people']::text[], 'human_performance', 'p-chco', 'Chief Human Capital Officer (role card)', 'الرئيس التنفيذي لرأس المال البشري (بطاقة دور)', 'pp', 'ytd', 'down', array['ISO30414']::text[], 'active', 7, 1, true)
insert into kafaa_national_tags (id, strategy, parent_id, kind, code, name_en, name_ar, summary_en, summary_ar, horizon_year, owner_en, owner_ar, sources, source_scope, source_note_en, source_note_ar, derive, future_group, status, sort, version, benchmark_ids, created_by, created_at, updated_by, updated_at) values
('nt-nes-2031', 'nes_2031', null, 'strategy', 'NES-2031', 'National Employment Strategy 2031', 'الاستراتيجية الوطنية للتوظيف 2031', 'Federal strategy adopted in 2018 to build labour-market skills, increase research and development personnel, expand lifelong learning and advance Emiratisation in sectors including artificial intelligence.', 'استراتيجية اتحادية اعتُمدت في 2018 لبناء مهارات سوق العمل وزيادة الكوادر العاملة في البحث والتطوير والتوسع في التعلم مدى الحياة وتعزيز التوطين في قطاعات منها الذكاء الاصطناعي.', 2031, null, null, '[{"label":"u.ae (UAE Government portal) · The National Employment Strategy 2031","url":"https://u.ae/about-the-uae/strategies-initiatives-and-awards/strategies-plans-and-visions/human-resources-development-and-education/the-national-employment-strategy-2031","as_of":"2026-10-10","tier":"official","year":null}]'::jsonb, 'direct', null, null, null, null, 'active', 1, 1, '{}'::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-nes-2031-skills', 'nes_2031', 'nt-nes-2031', 'goal', 'NES-SKILLS', 'Build labour-market skills', 'بناء مهارات سوق العمل', 'The strategy goal of building the skills the labour market needs; at ENEC, the future-skills courses, academies and the critical skills register serve it.', 'هدف الاستراتيجية في بناء المهارات التي يحتاجها سوق العمل؛ وفي المؤسسة تخدمه مقررات مهارات المستقبل والأكاديميات وسجل المهارات الحرجة.', 2031, null, null, '[{"label":"u.ae (UAE Government portal) · The National Employment Strategy 2031","url":"https://u.ae/about-the-uae/strategies-initiatives-and-awards/strategies-plans-and-visions/human-resources-development-and-education/the-national-employment-strategy-2031","as_of":"2026-10-10","tier":"official","year":null}]'::jsonb, 'direct', null, null, null, null, 'active', 1, 1, '{}'::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-nes-2031-rnd', 'nes_2031', 'nt-nes-2031', 'goal', 'NES-RND', 'Increase research and development personnel', 'زيادة الكوادر العاملة في البحث والتطوير', 'The strategy goal of growing research and development personnel; graduate study and scholarship routes into nuclear engineering serve it.', 'هدف الاستراتيجية في زيادة الكوادر العاملة في البحث والتطوير؛ وتخدمه مسارات الدراسات العليا والمنح الدراسية في الهندسة النووية.', 2031, null, null, '[{"label":"u.ae (UAE Government portal) · The National Employment Strategy 2031","url":"https://u.ae/about-the-uae/strategies-initiatives-and-awards/strategies-plans-and-visions/human-resources-development-and-education/the-national-employment-strategy-2031","as_of":"2026-10-10","tier":"official","year":null}]'::jsonb, 'direct', null, null, null, null, 'active', 2, 1, '{}'::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-nes-2031-lifelong', 'nes_2031', 'nt-nes-2031', 'goal', 'NES-LIFELONG', 'Expand lifelong learning', 'التوسع في التعلم مدى الحياة', 'The strategy goal of expanding lifelong learning; learning pathways, stackable micro-credentials and the curiosity and lifelong learning skill serve it.', 'هدف الاستراتيجية في التوسع في التعلم مدى الحياة؛ وتخدمه مسارات التعلم والشهادات المصغّرة القابلة للتجميع ومهارة الفضول والتعلم مدى الحياة.', 2031, null, null, '[{"label":"u.ae (UAE Government portal) · The National Employment Strategy 2031","url":"https://u.ae/about-the-uae/strategies-initiatives-and-awards/strategies-plans-and-visions/human-resources-development-and-education/the-national-employment-strategy-2031","as_of":"2026-10-10","tier":"official","year":null}]'::jsonb, 'direct', null, null, null, null, 'active', 3, 1, '{}'::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-nes-2031-emiratisation', 'nes_2031', 'nt-nes-2031', 'goal', 'NES-EMIRATI', 'Emiratisation in priority sectors, including AI', 'التوطين في القطاعات ذات الأولوية بما فيها الذكاء الاصطناعي', 'The strategy goal of Emiratisation; Nafis and the Emirati Talent Competitiveness Council carry it into the private sector. ENEC''s Emirati talent programmes serve it.', 'هدف الاستراتيجية في التوطين؛ ويحمله برنامج نافس ومجلس تنافسية الكوادر الإماراتية إلى القطاع الخاص، وتخدمه برامج المؤسسة للكفاءات الإماراتية.', 2031, 'Emirati Talent Competitiveness Council with MoHRE (Nafis)', 'مجلس تنافسية الكوادر الإماراتية مع وزارة الموارد البشرية والتوطين (نافس)', '[{"label":"u.ae (UAE Government portal) · The National Employment Strategy 2031","url":"https://u.ae/about-the-uae/strategies-initiatives-and-awards/strategies-plans-and-visions/human-resources-development-and-education/the-national-employment-strategy-2031","as_of":"2026-10-10","tier":"official","year":null},{"label":"WAM · Emiratisation agenda advances with leadership support, private sector partnership","url":"https://www.wam.ae/en/article/c1betlp-emiratisation-agenda-advances-with-leadership","as_of":"2026-10-10","tier":"official","year":2026}]'::jsonb, 'direct', null, null, null, null, 'active', 4, 1, array['NAFIS']::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-we-uae-2031', 'we_uae_2031', null, 'strategy', 'WE-UAE-2031', 'We the UAE 2031', 'نحن الإمارات 2031', 'National vision with a Forward Society pillar (lifelong learning, skilled minds) and a Forward Economy pillar (attracting global talent), nested inside UAE Centennial 2071.', 'رؤية وطنية تضم ركيزة مجتمع متقدّم (التعلم مدى الحياة والعقول الماهرة) وركيزة اقتصاد متقدّم (استقطاب المواهب العالمية)، ضمن مئوية الإمارات 2071.', 2031, null, null, '[{"label":"UN-ESCWA Arab National Development Planning portal · We the UAE 2031","url":"https://andp.unescwa.org/plans/1491","as_of":"2026-10-10","tier":"intergovernmental","year":null},{"label":"Al Ghurair Foundation · UAE Skills (PDF)","url":"https://www.alghurairfoundation.org/wp-content/uploads/2025/12/UAE-Skills-En-251210.pdf","as_of":"2026-10-10","tier":"secondary","year":2025}]'::jsonb, 'direct', 'The research pack cites this vision through the UN-ESCWA planning portal and a foundation paper, not a UAE government page, and found no skills target attributable to the vision itself. Re-check the official page before external reporting.', 'يستشهد ملف البحث بهذه الرؤية عبر بوابة التخطيط التابعة للإسكوا وورقة صادرة عن مؤسسة، لا عبر صفحة حكومية إماراتية، ولم يجد هدفاً للمهارات منسوباً إلى الرؤية نفسها. يُرجى التحقق من الصفحة الرسمية قبل أي تقرير خارجي.', null, null, 'active', 2, 1, '{}'::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-we-uae-2031-society', 'we_uae_2031', 'nt-we-uae-2031', 'pillar', 'WE-SOCIETY', 'Forward Society pillar', 'ركيزة مجتمع متقدّم', 'The pillar on lifelong learning and skilled minds; ENEC''s future-skills pack, AI Academy and systems-thinking credential serve it.', 'الركيزة المعنية بالتعلم مدى الحياة والعقول الماهرة؛ وتخدمها حزمة مهارات المستقبل وأكاديمية الذكاء الاصطناعي وشهادة التفكير المنظومي.', 2031, null, null, '[{"label":"UN-ESCWA Arab National Development Planning portal · We the UAE 2031","url":"https://andp.unescwa.org/plans/1491","as_of":"2026-10-10","tier":"intergovernmental","year":null},{"label":"Al Ghurair Foundation · UAE Skills (PDF)","url":"https://www.alghurairfoundation.org/wp-content/uploads/2025/12/UAE-Skills-En-251210.pdf","as_of":"2026-10-10","tier":"secondary","year":2025}]'::jsonb, 'direct', 'Cited, like the vision, through the UN-ESCWA planning portal and a foundation paper, not a UAE government page. Re-check before external reporting.', 'يُستشهد بها، مثل الرؤية، عبر بوابة التخطيط التابعة للإسكوا وورقة صادرة عن مؤسسة، لا عبر صفحة حكومية إماراتية. يُرجى التحقق قبل أي تقرير خارجي.', null, null, 'active', 1, 1, '{}'::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-we-uae-2031-economy', 'we_uae_2031', 'nt-we-uae-2031', 'pillar', 'WE-ECONOMY', 'Forward Economy pillar', 'ركيزة اقتصاد متقدّم', 'The pillar on attracting global talent; international leadership exposure and graduate study in nuclear engineering serve it.', 'الركيزة المعنية باستقطاب المواهب العالمية؛ ويخدمها الاحتكاك القيادي الدولي والدراسات العليا في الهندسة النووية.', 2031, null, null, '[{"label":"UN-ESCWA Arab National Development Planning portal · We the UAE 2031","url":"https://andp.unescwa.org/plans/1491","as_of":"2026-10-10","tier":"intergovernmental","year":null},{"label":"Al Ghurair Foundation · UAE Skills (PDF)","url":"https://www.alghurairfoundation.org/wp-content/uploads/2025/12/UAE-Skills-En-251210.pdf","as_of":"2026-10-10","tier":"secondary","year":2025}]'::jsonb, 'direct', 'Cited, like the vision, through the UN-ESCWA planning portal and a foundation paper, not a UAE government page. Re-check before external reporting.', 'يُستشهد بها، مثل الرؤية، عبر بوابة التخطيط التابعة للإسكوا وورقة صادرة عن مؤسسة، لا عبر صفحة حكومية إماراتية. يُرجى التحقق قبل أي تقرير خارجي.', null, null, 'active', 2, 1, '{}'::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-ai-2031', 'ai_2031', null, 'strategy', 'AI-2031', 'UAE National AI Strategy 2031', 'الاستراتيجية الوطنية للذكاء الاصطناعي 2031', 'National policy that embeds AI literacy, alongside the UAE AI Charter, with free public AI courses and an AI curriculum in schools; in Abu Dhabi the Department of Government Enablement runs AiNative, practical AI-tools training for government employees.', 'سياسة وطنية تُرسّخ الإلمام بالذكاء الاصطناعي إلى جانب ميثاق الإمارات للذكاء الاصطناعي، مع دورات عامة مجانية ومنهج للذكاء الاصطناعي في المدارس؛ وفي أبوظبي تدير دائرة التمكين الحكومي برنامج AiNative للتدريب العملي على أدوات الذكاء الاصطناعي لموظفي الحكومة.', 2031, null, null, '[{"label":"Khaleej Times · Abu Dhabi to train government employees in AI by 2027","url":"https://www.khaleejtimes.com/abu-dhabi-train-23000-government-employees-ai-by-2027","as_of":"2026-10-10","tier":"secondary","year":2025},{"label":"Abu Dhabi Department of Government Enablement · What we do","url":"https://dge.gov.ae/en/what-we-do","as_of":"2026-10-10","tier":"official","year":null},{"label":"Communicate Online · UAE embeds AI literacy into national strategy to boost workforce skills","url":"https://communicateonline.me/news/uae-embeds-ai-literacy-into-national-strategy-to-boost-workforce-skills-coursera/","as_of":"2026-10-10","tier":"secondary","year":2025}]'::jsonb, 'direct', 'The research pack holds no page of the strategy itself: the official source is the Abu Dhabi DGE remit page, and the AiNative training target is shown from the benchmark registry, not typed here.', 'لا يضم ملف البحث صفحة للاستراتيجية نفسها: المصدر الرسمي هو صفحة اختصاصات دائرة التمكين الحكومي في أبوظبي، ويُعرض هدف تدريب AiNative من سجل المعايير المرجعية لا مكتوباً هنا.', null, null, 'active', 3, 1, array['UAE-AI']::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-ai-2031-literacy', 'ai_2031', 'nt-ai-2031', 'goal', 'AI-LITERACY', 'AI literacy for the workforce', 'الإلمام بالذكاء الاصطناعي للقوى العاملة', 'AI literacy embedded as national policy; ENEC''s governed AI literacy, AI output verification and responsible data handling serve it.', 'الإلمام بالذكاء الاصطناعي بوصفه سياسة وطنية؛ ويخدمه في المؤسسة الإلمام المحوكم بالذكاء الاصطناعي والتحقق من مخرجاته والتعامل المسؤول مع البيانات.', 2031, null, null, '[{"label":"Abu Dhabi Department of Government Enablement · What we do","url":"https://dge.gov.ae/en/what-we-do","as_of":"2026-10-10","tier":"official","year":null},{"label":"Communicate Online · UAE embeds AI literacy into national strategy to boost workforce skills","url":"https://communicateonline.me/news/uae-embeds-ai-literacy-into-national-strategy-to-boost-workforce-skills-coursera/","as_of":"2026-10-10","tier":"secondary","year":2025}]'::jsonb, 'direct', null, null, null, null, 'active', 1, 1, array['UAE-AI']::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-ai-2031-ainative', 'ai_2031', 'nt-ai-2031', 'goal', 'AI-AINATIVE', 'AiNative: practical AI tools at work', 'AiNative: أدوات الذكاء الاصطناعي العملية في العمل', 'Abu Dhabi''s practical AI-tools training across government; ENEC''s AI Academy and automation design skill follow the same practical, governed approach.', 'تدريب أبوظبي العملي على أدوات الذكاء الاصطناعي في الجهات الحكومية؛ وتتبع أكاديمية الذكاء الاصطناعي في المؤسسة ومهارة تصميم الأتمتة النهج العملي المحوكم ذاته.', 2027, 'Abu Dhabi Department of Government Enablement (DGE)', 'دائرة التمكين الحكومي في أبوظبي', '[{"label":"Abu Dhabi Department of Government Enablement · What we do","url":"https://dge.gov.ae/en/what-we-do","as_of":"2026-10-10","tier":"official","year":null},{"label":"Khaleej Times · Abu Dhabi to train government employees in AI by 2027","url":"https://www.khaleejtimes.com/abu-dhabi-train-23000-government-employees-ai-by-2027","as_of":"2026-10-10","tier":"secondary","year":2025}]'::jsonb, 'direct', null, null, null, null, 'active', 2, 1, array['UAE-AI']::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-net-zero-2050', 'net_zero_2050', null, 'strategy', 'NET-ZERO-2050', 'UAE Net Zero 2050 strategic initiative', 'مبادرة الإمارات الاستراتيجية للحياد المناخي 2050', 'The national net-zero goal. Kafa''a links it to CleanEnergyComp, the sustainability competence framework, and to the New Economy group of the federal Jahiz platform, which covers net zero and climate change.', 'الهدف الوطني للحياد المناخي. تربطه كفاءة بإطار كفاءات الطاقة النظيفة للاستدامة، وبمجموعة مهارات الاقتصاد الجديد في منصة جاهز الاتحادية التي تشمل الحياد المناخي وتغيّر المناخ.', 2050, null, null, '[{"label":"WAM · Jahiz, UAE''s digital platform for upskilling all federal government talents with future skills","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10","tier":"official","year":2022}]'::jsonb, 'indirect', 'Indirect source: the research pack cites net zero through the Jahiz New Economy group, not the strategy''s own page. Re-check the government page before external reporting.', 'مصدر غير مباشر: يستشهد ملف البحث بالحياد المناخي عبر مجموعة الاقتصاد الجديد في منصة جاهز، لا عبر صفحة المبادرة نفسها. يُرجى التحقق من الصفحة الحكومية قبل أي تقرير خارجي.', 'cec_net_zero', null, 'active', 4, 1, '{}'::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-jahiz', 'jahiz', null, 'strategy', 'JAHIZ', 'Jahiz future-skills groups', 'مجموعات مهارات المستقبل في منصة جاهز', 'Federal future-skills platform launched in November 2022 for all federal government employees, built with government entities and global companies; its skills sit in four groups and build a Future Skills Wallet linked to performance management.', 'منصة اتحادية لمهارات المستقبل أُطلقت في نوفمبر 2022 لجميع موظفي الحكومة الاتحادية، بُنيت مع جهات حكومية وشركات عالمية؛ تتوزع مهاراتها على أربع مجموعات وتبني محفظة لمهارات المستقبل مرتبطة بإدارة الأداء.', null, 'Government Development and the Future Office with FAHR', 'مكتب تطوير الحكومة والمستقبل مع الهيئة الاتحادية للموارد البشرية الحكومية', '[{"label":"WAM · Jahiz, UAE''s digital platform for upskilling all federal government talents with future skills","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10","tier":"official","year":2022},{"label":"u.ae · Strategies for improving digital skills and eGovernment literacy","url":"https://u.ae/en/information-and-services/jobs/training-and-development/Strategies-for-improving-digital-skills-and-eGovernment-literacy","as_of":"2026-10-10","tier":"official","year":null},{"label":"FAHR · A new partnership between the Authority and global platform Udacity","url":"https://www.fahr.gov.ae/en/news/a-new-partnership-between-the-authority-and-global-platform-udacity/","as_of":"2026-10-10","tier":"official","year":2024}]'::jsonb, 'direct', null, null, null, null, 'active', 5, 1, array['JAHIZ']::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-jahiz-digital', 'jahiz', 'nt-jahiz', 'group', 'JAHIZ-DIGITAL', 'Digital Skills', 'المهارات الرقمية', 'Jahiz group for digital skills. Catalogue skills in this group are linked automatically from their Jahiz group in the skills catalogue.', 'مجموعة جاهز للمهارات الرقمية. تُربط مهارات الدليل في هذه المجموعة تلقائياً من مجموعة جاهز المسجلة لها في دليل المهارات.', null, null, null, '[{"label":"WAM · Jahiz, UAE''s digital platform for upskilling all federal government talents with future skills","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10","tier":"official","year":2022},{"label":"u.ae · Strategies for improving digital skills and eGovernment literacy","url":"https://u.ae/en/information-and-services/jobs/training-and-development/Strategies-for-improving-digital-skills-and-eGovernment-literacy","as_of":"2026-10-10","tier":"official","year":null}]'::jsonb, 'direct', null, null, 'future_group', 'digital', 'active', 1, 1, array['JAHIZ']::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-jahiz-10x', 'jahiz', 'nt-jahiz', 'group', 'JAHIZ-10X', '10X Skills', 'مهارات 10X', 'Jahiz group for the human skills that multiply impact. Catalogue skills in this group are linked automatically from their Jahiz group.', 'مجموعة جاهز للمهارات الإنسانية التي تضاعف الأثر. تُربط مهارات الدليل في هذه المجموعة تلقائياً من مجموعة جاهز المسجلة لها.', null, null, null, '[{"label":"WAM · Jahiz, UAE''s digital platform for upskilling all federal government talents with future skills","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10","tier":"official","year":2022},{"label":"u.ae · Strategies for improving digital skills and eGovernment literacy","url":"https://u.ae/en/information-and-services/jobs/training-and-development/Strategies-for-improving-digital-skills-and-eGovernment-literacy","as_of":"2026-10-10","tier":"official","year":null}]'::jsonb, 'direct', null, null, 'future_group', 'ten_x', 'active', 2, 1, array['JAHIZ']::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-jahiz-data-ai', 'jahiz', 'nt-jahiz', 'group', 'JAHIZ-DATA-AI', 'Data & AI Skills', 'مهارات البيانات والذكاء الاصطناعي', 'Jahiz group for data and artificial intelligence skills. Catalogue skills in this group are linked automatically from their Jahiz group.', 'مجموعة جاهز لمهارات البيانات والذكاء الاصطناعي. تُربط مهارات الدليل في هذه المجموعة تلقائياً من مجموعة جاهز المسجلة لها.', null, null, null, '[{"label":"WAM · Jahiz, UAE''s digital platform for upskilling all federal government talents with future skills","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10","tier":"official","year":2022},{"label":"u.ae · Strategies for improving digital skills and eGovernment literacy","url":"https://u.ae/en/information-and-services/jobs/training-and-development/Strategies-for-improving-digital-skills-and-eGovernment-literacy","as_of":"2026-10-10","tier":"official","year":null}]'::jsonb, 'direct', null, null, 'future_group', 'data_ai', 'active', 3, 1, array['JAHIZ']::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-jahiz-new-economy', 'jahiz', 'nt-jahiz', 'group', 'JAHIZ-NEW-ECONOMY', 'New Economy Skills', 'مهارات الاقتصاد الجديد', 'Jahiz group covering net zero and climate change, circular economy and sustainability, the digital economy and new economy models. Catalogue skills in this group are linked automatically.', 'مجموعة جاهز التي تشمل الحياد المناخي وتغيّر المناخ والاقتصاد الدائري والاستدامة والاقتصاد الرقمي ونماذج الاقتصاد الجديد. تُربط مهارات الدليل في هذه المجموعة تلقائياً.', null, null, null, '[{"label":"WAM · Jahiz, UAE''s digital platform for upskilling all federal government talents with future skills","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10","tier":"official","year":2022},{"label":"u.ae · Strategies for improving digital skills and eGovernment literacy","url":"https://u.ae/en/information-and-services/jobs/training-and-development/Strategies-for-improving-digital-skills-and-eGovernment-literacy","as_of":"2026-10-10","tier":"official","year":null}]'::jsonb, 'direct', null, null, 'future_group', 'new_economy', 'active', 4, 1, array['JAHIZ']::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z'),
('nt-centennial-2071', 'centennial_2071', null, 'strategy', 'CENTENNIAL-2071', 'UAE Centennial 2071', 'مئوية الإمارات 2071', 'The long-term national vision within which We the UAE 2031 sits. For a plant licensed to operate for decades it frames multi-generation workforce planning; advanced-reactor learning here is concept learning, with no deployment decision implied.', 'الرؤية الوطنية بعيدة المدى التي تندرج ضمنها رؤية نحن الإمارات 2031. ولمحطة مرخّصة للتشغيل لعقود فهي إطار لتخطيط القوى العاملة عبر الأجيال؛ والتعلم عن المفاعلات المتقدمة هنا تعلّم مفاهيمي، ولا يُفهم منه أي قرار بالنشر.', 2071, null, null, '[{"label":"UN-ESCWA Arab National Development Planning portal · We the UAE 2031","url":"https://andp.unescwa.org/plans/1491","as_of":"2026-10-10","tier":"intergovernmental","year":null},{"label":"Al Ghurair Foundation · UAE Skills (PDF)","url":"https://www.alghurairfoundation.org/wp-content/uploads/2025/12/UAE-Skills-En-251210.pdf","as_of":"2026-10-10","tier":"secondary","year":2025}]'::jsonb, 'direct', 'The research pack cites the Centennial through the UN-ESCWA planning portal and a foundation paper, not a UAE government page. Re-check the official page before external reporting.', 'يستشهد ملف البحث بالمئوية عبر بوابة التخطيط التابعة للإسكوا وورقة صادرة عن مؤسسة، لا عبر صفحة حكومية إماراتية. يُرجى التحقق من الصفحة الرسمية قبل أي تقرير خارجي.', null, null, 'active', 6, 1, '{}'::text[], 'p-chco', '2026-10-11T08:00:00Z', 'p-chco', '2026-10-11T08:00:00Z')
